y_spoken'] = sp(today)\nexcept Exception:\n    vars['callback_window_text'] = 'A callback can only be booked on a business day between 10:00 and 18:00, later than now.'\n    vars['today_spoken'] = ''\n"}, "timeout_ms": {"type": "number", "default": 10000}}}}}],
