):\n        s = re.sub(r'\\b' + w + r'\\b', str(n) + 'th', s)\n    mon = None\n    for i, n in enumerate(MO):\n        if re.search(r'\\b' + n[:3], s):\n            mon = i + 1\n    m = re.search(r'\\b(\\d{1,2})(st|nd|rd|th)?\\b', s)\n    if m and (mon or m.group(2)):\n        day = int(m.group(1))\n        for k in range(0, 14):\n            y = today.year + (today.month - 1 + k) // 12\n            mo = (today.month - 1 + k) % 12 + 1\n            if mon and mo != mon:\n                continue\n            try:\n                c = datetime.date(y, mo, day)\n            except ValueError:\n                continue\n            if c >= today:\n                return c\n        return None\n    if 'day after tomorrow' in s:\n        return today + datetime.timedelta(days=2)\n    if 'tomorrow' in s:\n        return today + datetime.timedelta(days=1)\n    if re.search(r'\\btoday\\b', s):\n        return today\n    mon0 = today - datetime.timedelta(days=today.weekday())\n    for i, n in enumerate(WD):\n        if n in s:\n            if re.search(r'next\\s+' + n, s):\n                return mon0 + datetime.timedelta(days=7 + i)\n            if re.search(r'this\\s+' + n, s):\n                return mon0 + datetime.timedelta(days=i)\n            d = mon0 + datetime.timedelta(days=i)\n            return d if d >= today else d + datetime.timedelta(days=7)\n    return None\n\nvars['store_state'] = 'corrected'\ntry:\n    today = pnow(vars.get('now')).date()\n    f = json.loads(vars.get('facts_json') or '{}')\n    dl = datetime.date.fromisoformat(f['deadline'])\n    words = str(vars.get('agreed_date_words') or '').strip()\n    raw = str(vars.get('agreed_amount') or '').strip().replace(',', '')\n    try:\n        amount = round(float(raw), 2) if raw else round(float(vars.get('offer_amount') or f['full']), 2)\n    except ValueError:\n        amount = round(float(vars.get('offer_amount') or f['full']), 2)\n    if amount <= 0 or amount > f['full']:\n        amount = f['full']\n    day = resolve(words, today) if words else datetime.date.fromisoformat(vars.get('offer_date'))\n    if day is None and vars.get('vague_asked') != 'yes':\n        vars['vague_asked'] = 'yes'\n        vars['offer_amount'] = str(amount)\n        vars['offer_text'] = 'Which exact day could you pay?'\n    elif day is None or day < today:\n        vars['offer_amount'] = str(amount)\n        vars['offer_date'] = dl.isoformat()\n        vars['offer_text'] = 'The latest date we can record is ' + sp(dl) + '. Could you pay ' + money(amount) + ' on ' + sp(dl) + '?'\n    elif day > dl or (not isbd(day) and nbd(day) > dl):\n        vars['offer_amount'] = str(amount)\n        vars['offer_date'] = dl.isoformat()\n        vars['offer_text'] = 'The latest date we can record is ' + sp(dl) + '. Could you pay ' + money(amount) + ' on ' + sp(dl) + '?'\n    elif not isbd(day):\n        nb = nbd(day)\n        vars['offer_amount'] = str(amount)\n        vars['offer_date'] = nb.isoformat()\n        vars['offer_text'] = sp(day) + ' is not a business day. Could you pay ' + money(amount) + ' on ' + sp(nb) + ' instead?'\n    elif amount < f['floor']:\n        if vars.get('floor_corrected') == 'yes':\n            vars['store_state'] = 'refused'\n        else:\n            vars['floor_corrected'] = 'yes'\n            vars['offer_amount'] = str(f['floor'])\n            vars['offer_date'] = day.isoformat()\n            vars['offer_is_floor'] = 'yes'\n            vars['offer_text'] = 'I cannot record less than ' + money(f['floor']) + '. Could you pay ' + money(f['floor']) + ' on ' + sp(day) + '? The rest of the overdue amount would stay overdue.'\n    else:\n        vars['agree_amount'] = amount\n        vars['agree_date'] = day.isoformat()\n        vars['readback_text'] = 'To confirm: a payment of ' + money(amount) + ' on your ' + f['name'] + ' on ' + sp(day) + '. Do you confirm?'\n        vars['store_state'] = 'stored'\nexcept Exception:\n    vars['offer_text'] = 'Which exact day could you pay, and