you pay ' + money(f['floor']) + ' on ' + sp(dl) + '? The rest of the overdue amount would stay overdue.'\n        vars['offer_amount'] = str(f['floor'])\n        vars['offer_date'] = dl.isoformat()\n        vars['offer_is_floor'] = 'yes'\n    else:\n        vars['offer_state'] = 'done'\n    vars['offer_step'] = str(step)\nexcept Exception:\n    vars['offer_state'] = 'done'\n"}, "timeout_ms": {"type": "number", "default": 10000}}}}}],
