   "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": "import datetime\nimport json\nimport re\nWD = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMO = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nHOL = set(datetime.date.fromisoformat(x) for x in ['2026-11-03', '2026-11-17', '2026-12-25', '2026-12-26', '2027-01-01'])\n\ndef pnow(v):\n    s = str(v or '').strip().replace(' ', 'T').rstrip('Z')\n    for f, n in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:n], f)\n        except ValueError:\n            pass\n    raise ValueError(s)\n\ndef isbd(d):\n    return d.weekday() < 5 and d not in HOL\n\ndef nbd(d):\n    d = d + datetime.timedelta(days=1)\n    while not isbd(d):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef addbd(d, n):\n    for _ in range(n):\n        d = nbd(d)\n    return d\n\ndef lbw(d):\n    mon = d - datetime.timedelta(days=d.weekday())\n    x = mon + datetime.timedelta(days=4)\n    while x >= mon:\n        if isbd(x):\n            return x\n        x = x - datetime.timedelta(days=1)\n    return None\n\ndef sp(d):\n    return WD[d.weekday()].title() + ' ' + str(d.day) + ' ' + MO[d.month - 1].title()\n\ndef money(a):\n    return '{:,.2f}'.format(round(float(a), 2))\n\ndef list_from_vars(vars, prefixes):\n    for p in prefixes:\n        rows = dict()\n        for k, v in vars.items():\n            k = str(k)\n            if k.startswith(p + '.'):\n                i, _, f = k[len(p) + 1:].partition('.')\n                if i.isdigit() and f:\n                    rows.setdefault(int(i), dict())[f] = v\n        if rows:\n            return [rows[i] for i in sorted(rows)]\n    for p in prefixes:\n        v = vars.get(p)\n        if isinstance(v, str):\n            try:\n                v = json.loads(v)\n            except ValueError:\n                v = None\n        if isinstance(v, list) and v:\n            return v\n    return []\n\ntry:\n    now = pnow(vars.get('now'))\n    today = now.date()\n    items = list_from_vars(vars, ['load_account_response.data.products', 'get_account_response.data.products'])\n    p = items[0]\n    t = str(p.get('type') or '')\n    if t == 'credit_card':\n        name = 'credit card ending ' + str(p.get('card_last4') or '')\n        floor = p.get('minimum_payment')\n    elif t == 'car_loan':\n        name = 'car loan'\n        floor = p.get('instalment_amount')\n    else:\n        name = 'personal loan'\n        floor = p.get('instalment_amount')\n    full = round(float(p.get('past_due') or 0), 2)\n    floor = round(float(floor or 0), 2)\n    if floor <= 0 or floor > full:\n        floor = full\n    days = int(float(p.get('days_late') or 0))\n    att = 1 if days <= 10 else 2\n    dl = addbd(today, 8 if days <= 10 else 4)\n    w = lbw(today)\n    if w is None or w <= today:\n        w = lbw(today + datetime.timedelta(days=7))\n    a1 = min(w, dl) if w else dl\n    pay_today = today if isbd(today) else nbd(today)\n    vars['prod_id'] = str(p.get('product_id') or '')\n    vars['prod_name'] = name\n    vars['facts_json'] = json.dumps(dict(name=name, full=full, floor=floor, days=days, attempts=att, deadline=dl.isoformat(), a1=a1.isoformat()))\n    rows = []\n    mon0 = today - datetime.timedelta(days=today.weekday())\n    for k in range(0, 21):\n        d = today + datetime.timedelta(days=k)\n        tag = 'business day' if isbd(d) else 'NOT a business day (next business day ' + sp(nbd(d)) + ')'\n        wk = (d - mon0).days // 7\n        rel = ' = this ' + WD[d.weekday()].title() if wk == 0 else (' = next ' + WD[d.weekday()].title() if wk == 1 else '')\n        rows.append('- ' + sp(d) + ' (' + d.isoformat() + ')' + rel + ': ' + tag + ('' if d <= dl else ', after the deadline'))\n    vars['facts_text'] = ('Today is ' + sp(today) + '. Product: ' + name + '. Overdue amount: ' + money(full) + '. Days late: ' + str(days) + '. Lowest amount that can be recorded: ' + money(floor) + '. Latest promise date (deadline): ' + sp(dl) + '. Dates:\\n' + '\\n'.join(rows))\n    vars['offer_text'] = 'This is the collections team calling about a late payment on your ' + name + '. The overdue amount is ' + money(full) + ', and it is ' + str(days) + ' days late. Can you make this payment today?'\n    vars['offer_amount'] = str(full)\n    vars['offer_date'] = pay_today.isoformat()\n    vars['offer_is_floor'] = 'no'\n    vars['offer_step'] = '0'\n    vars['floor_mode'] = 'no'\n    vars['floor_corrected'] = 'no'\n    vars['vague_asked'] = 'no'\n    vars['offer_answer'] = 'stay'\n    vars['facts_state'] = 'ok'\nexcept Exception:\n    vars['facts_text'] = 'The account details could not be read.'\n    vars['facts_json'] = '{}'\n    vars['offer_text'] = ''\n    vars['facts_state'] = 'error'\n"}, "timeout_ms": {"type": "number", "default": 10000}}}}}],
